    out = [row[:] for row in grid]

    # Grid lines partition the image into cells. Within each horizontal
    # band, reflect a nonempty cell into an adjacent empty cell.
    rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb = [-1] + rows + [h]
    cb = [-1] + cols + [w]

    for ri in range(len(rb) - 1):
        top, bottom = rb[ri] + 1, rb[ri + 1]
        for ci in range(len(cb) - 2):
            left1, right1 = cb[ci] + 1, cb[ci + 1]
            left2, right2 = cb[ci + 1] + 1, cb[ci + 2]
            height = bottom - top
            width = min(right1 - left1, right2 - left2)
            if height <= 0 or width <= 0:
                continue

            a = [[grid[r][c] for c in range(left1, left1 + width)]
                 for r in range(top, bottom)]
            b = [[grid[r][c] for c in range(left2, left2 + width)]
                 for r in range(top, bottom)]
            has_a = any(x not in (0, 8) for row in a for x in row)
            has_b = any(x not in (0, 8) for row in b for x in row)

            if has_a and not has_b:
                for r in range(height):
                    for c in range(width):
                        v = a[r][width - 1 - c]
                        if v not in (0, 8):
                            out[top + r][left2 + c] = v
            elif has_b and not has_a:
                for r in range(height):
                    for c in range(width):
                        v = b[r][width - 1 - c]
                        if v not in (0, 8):
